return {
  [ [[v5748eaic9ne9]] ] = { t = [[黑暗术与日光杖]], q = [=[在黑暗术的区域内增加更多[[日光杖]]，能提高光照等级吗？]=], a = [[不能。日光杖永远无法提高黑暗术区域的光照等级，因为它们不是魔法光源。在这样的区域中，光照等级会自动取周围的自然光照等级（来自太阳、月亮和星辰等自然光源的光照等级，不包括火把、营火、光亮法术等），然后再下降1级。]], book = [[核心规则书]], date = [[2010/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9ne9]], cat = [[FAQ]], ai = true, pages = { [[黑暗术]] } },
  [ [[v5748eaic9qnn]] ] = { t = [[黑暗术与非魔法光源]], q = [[如果非魔法光源位于黑暗术的区域之外，它能提高区域内的光照等级吗？]], a = [[不能。无论非魔法光源位于法术区域之内还是之外，都不会提高法术区域内的光照等级。]], book = [[核心规则书]], date = [[2013/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qnn]], cat = [[FAQ]], ai = true, pages = { [[黑暗术]] } },
  [ [[v5748eaic9qlm]] ] = { t = [[透过黑暗看光源]], q = [[我能透过黑暗术的区域看到光源吗？]], a = [[不能。如果黑暗术将区域内的光照降到了真正的黑暗（若使用更强力的法术，则是超自然黑暗），你就无法透过这片黑暗看到其后的事物。]], book = [[核心规则书]], date = [[2013/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qlm]], cat = [[FAQ]], ai = true, pages = { [[黑暗术]] } },
  [ [[v5748eaic9o3r]] ] = { t = [[护体与攻击检定]], q = [[我必须用这把武器进行攻击检定，才能获得护体武器的AC加值吗？]], a = [[是的。仅仅持有护体武器并不够。除非另有说明，你必须按魔法物品设计的用法来使用它（用武器进行攻击，把盾牌戴在手臂上以便用来防御，等等），才能获得它的益处。

因此，如果你在自己的回合内没有用护体武器进行攻击检定，就得不到它的防御益处。

同样，你可以给盾牌附上护体属性（当然，要先给它+1的增强加值），但除非你在那一轮用盾牌进行了盾击，否则你得不到护体属性的AC加值——只要你没有把盾牌当作武器使用（进行盾击），护体武器属性就没有任何效果。]], book = [[核心规则书]], date = [[2011/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o3r]], cat = [[FAQ]], ai = true, pages = { [[护体]] } },
  [ [[v5748eaic9v29]] ] = { t = [[反射豁免与无法动弹]], q = [=[如果我被[[麻痹]]、被定身、[[濒死]]，或以其他方式完全无法动弹或失去知觉，我还能进行反射豁免吗？]=], a = [=[可以，你仍能进行反射豁免，但由于你的敏捷被视为0，你必须用–5减值来取代敏捷加值，所以多半不会成功。如果你成功了，可能是因为[[抗力披风]]的力量、有利的掩护角度，甚至纯粹是运气。无论如何，成功的反射豁免都要按法术的规定处理，即使这会改变你所占的空间，比如[[造坑术]]。不过在这种情形下你会失去反射闪避。如果你受到某种罕见效果的影响而无法动弹或失去知觉，并且该效果允许你持续进行反射豁免来挣脱，那么作为规则的例外，你可以仅在为了这些持续豁免时使用完整的敏捷加值（而不是–5减值），因为你的全部敏捷正在法术的限制范围内努力挣脱。]=], book = [[核心规则书]], date = [[2016/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9v29]], cat = [[FAQ]], ai = true, pages = { [[战斗中的数据计算]], [[麻痹]] } },
  [ [[v5748eaic9o91]] ] = { t = [[高属性的奖励法术]], q = [[我能在施法职业等级不足以使用相应法术环级时，使用高属性带来的这些奖励法术吗？]], a = [[不能。只有当你的职业等级允许你使用相应的法术环级时，你才能获得对应的奖励法术。你甚至不能把它们用在较低环级的法术上。参阅第16页《属性与施法者》一节：“除了拥有较高的属性值，施法者必须拥有足够高的职业等级才能施展对应环级的法术。”

举例而言，一位智力18的1级法师在1环、2环和3环各有1个奖励法术（参阅《表1-3：属性修正与奖励法术》）。然而由于他只是1级法师，只有使用1环法术的能力（他按职业每日可施展的2环和3环法术数为“—”，意味着“无权使用此环级的法术”），因此只能使用1环的那个奖励法术。当他成为3级法师、获得使用2环法术的能力时，就能使用高智力带来的2环奖励法术，3环法术和5级法师的情形也类似。

一般而言，在你的职业给予你使用相应环级法术的能力之前，请忽略《表1-3：属性修正与奖励法术》中较高环级法术的那些栏目。]], book = [[核心规则书]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o91]], cat = [[FAQ]], ai = false, pages = { [[属性]] } },
  [ [[v5748eaic9nv6]] ] = { t = [[任意门与同行者]], q = [[如果施法者携带其他生物一同施放该法术，是这些同行者也在下个回合之前不能进行其他动作，还是仅施法者如此？]], a = [[该限制只适用于施法者。]], book = [[核心规则书]], date = [[2011/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9nv6]], cat = [[FAQ]], ai = true, pages = { [[任意门]] } },
  [ [[v5748eaic9qfa]] ] = { t = [[精明防御与CMD]], q = [[决斗家的【精明防御】能力是否会加到CMD上？]], a = [[自《核心规则书》第6次印刷起，【精明防御】能力给予AC的闪避加值，因此会提高决斗家的CMD。

（第6次印刷之前，【精明防御】的加值不属于CMD规则中列出的加值类型，因此不会加到CMD上。）

更新于2013年8月26日：已改为反映该能力在第6次印刷中的修订文本。]], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qfa]], cat = [[FAQ]], ai = false, pages = { [[决斗家]] } },
  [ [[v5748eaic9qdi]] ] = { t = [[精明防御与最大敏捷加值]], q = [[决斗家的【精明防御】能力是否受盔甲的最大敏捷加值限制？]], a = [[决斗家将其智力加值（而不是敏捷加值）加到AC上。在任何会使她失去AC敏捷加值的情形下，她都会失去这个基于智力的AC加值。

由于基于智力的AC加值不是敏捷加值，它不受盔甲最大敏捷加值的限制。

（这项智力加值也适用于角色的接触AC。）]], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qdi]], cat = [[FAQ]], ai = false, pages = { [[决斗家]] } },
  [ [[v5748eaic9o71]] ] = { t = [[法术强效与固定加值]], q = [=[如果我对带有骰子和数值加值的法术（比如[[治疗中伤]]）使用法术强效，该专长会影响这个数值加值吗？]=], a = [[会。例如，如果你对治疗中伤使用法术强效，专长的+50%会同时作用于2d8和基于等级的加值。]], book = [[核心规则书]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o71]], cat = [[FAQ]], ai = true, pages = { [[法术强效]] } },
  [ [[v5748eaic9r9f]] ] = { t = [[能量吸取与即死效果]], q = [=[[[能量吸取(怪物能力)|能量吸取]]算作即死效果吗？]=], a = [=[能量吸取不是即死效果。

不死生物类型把对“即死效果”和“能量吸取”的免疫分别列出，说明它们是两回事。《核心规则书》中“即死攻击”的描述没有提到负向等级或能量吸取。“能量吸取和负向等级”在《核心规则书》中是一个完全独立的条目，既没有说能量吸取是即死攻击的一种，也没有说[[防死结界]]能防护它们。

防死结界给予对即死法术和魔法即死效果的加值，接着又说目标免疫能量吸取，并在法术持续期间中止负向等级带来的减值。

因此规则把能量吸取和即死效果视为不同的东西。例如，如果你免疫即死效果，并不意味着你一定免疫能量吸取。]=], book = [[核心规则书]], date = [[2013/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9r9f]], cat = [[FAQ]], ai = false, pages = { [[能量吸取(怪物能力)]], [[特殊能力]] } },
  [ [[v5748eaic9vu4]] ] = { t = [[负向等级的永久化]], q = [=[第562页说你每天有一次豁免来移除临时负向等级，但[[通用怪物规则]]中的能量吸取，以及我能找到的几乎所有提到临时负向等级的地方，都说如果我豁免失败，24小时后临时负向等级会变成永久的。哪个才对？]=], a = [=[第562页的规则是一般规则，但游戏中几乎每条具体规则的运作方式都与它不同，而具体规则优先于一般规则。顺带一提，通用怪物规则中的能量吸取并没有明确说明负向等级在变成永久之前被视为临时的（它只说了“负向等级”），而我们想要明确指出，它们在那时是临时负向等级（因此你可以用[[复原术]]以更低廉的代价移除它们）。唯一直接出错的文字，是[[弱能术]]末尾的提醒文字，它声称24小时后变成永久是一般规则。]=], book = [[核心规则书]], date = [[2017/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9vu4]], cat = [[FAQ]], ai = true, pages = { [[特殊能力]], [[能量吸取(怪物能力)]] } },
  [ [[v5748eaic9o82]] ] = { t = [[额外引导与兼职]], q = [=[如果我拥有多个能够[[引导能量]]的职业并选择了此专长，我必须在选择该专长时指定额外次数属于哪个职业吗？]=], a = [[不需要。实际上，本专长给予你每天2次“浮动的”引导能量使用次数，你可以将它们用于你拥有的任何给予引导能量能力的职业。

举例而言，如果你是一名牧师/死灵师，每天你可以用1次作为牧师引导、1次作为死灵师引导，或2次作为牧师、0次作为死灵师，或0次作为牧师、2次作为死灵师。

注意，本专长不会让你拥有的每个给予引导能量的职业各获得2次额外使用次数——它每天恰好只提供2次额外使用次数。]], book = [[核心规则书]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o82]], cat = [[FAQ]], ai = false, pages = { [[额外引导]] } },
  [ [[v5748eaic9qp3]] ] = { t = [[鬼斧神工与精制品]], q = [[我能用鬼斧神工制作精制物品或使用特殊材料的物品吗？]], a = [=[可以，两者都可以。实际上，该法术只是比非魔法制作节省时间；你仍然必须提供原材料（花费相当于物品价格的1/3）。

如果制作的物品不需要很高的工艺水平，比如桌子、门、棍棒、服装或简易的护甲，该法术不需要进行[[工艺]]检定。

制作带有暗格的桌子、关上时与墙壁融为一体的门（即暗门），或精制物品，都算作需要“很高工艺水平”的物品，所以你必须对制作这类物品的DC通过相应的工艺检定。一般而言，任何工艺DC为15或更高的物品，都要求你通过工艺检定才能用该法术制作。

举例来说，如果你想制作一件[[秘银]][[链甲衫]]，就需要提供秘银和链甲衫所需的其他材料（花费物品价格的1/3）。由于秘银物品永远是精制的，你必须通过工艺检定才能成功制作该物品。

和一般的制作规则一样，如果这次检定失败的差值在4以内，你制作物品失败但不会毁掉材料（并可以用这些材料再次施放该法术）。如果失败的差值为5或更多，你会毁掉一半的原材料，必须再支付一半的原材料原价。]=], book = [[核心规则书]], date = [[2013/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qp3]], cat = [[FAQ]], ai = true, pages = { [[鬼斧神工]] } },
  [ [[v5748eaic9o4s]] ] = { t = [[战士重训1级专长]], q = [=[我能用战士奖励专长的职业特性来[[重训]]1级时获得的专长（比如[[顺势斩]]），以换取一项我在1级时不满足条件、而现在满足条件的专长（比如[[突刺]]）吗？]=], a = [[可以。只要你“失去”的那项专长不是任何其他专长、进阶职业或能力的先决条件，你就能获得任何在你重训时满足条件的专长。]], book = [[核心规则书]], date = [[2011/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o4s]], cat = [[FAQ]], ai = false, pages = { [[战士]] } },
  [ [[v5748eaic9qdj]] ] = { t = [[战士与防具擅长]], q = [[我能学习一项新的战士奖励专长来取代我的防具擅长专长吗？]], a = [[不能。尽管防具擅长专长的文字有这样的说法，战士（及其他职业）拥有的是一项给予这些防具擅长的职业能力——它并没有真的给予这些具体的专长。因此，战士以新专长取代旧专长的能力不适用于这些擅长。]], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qdj]], cat = [[FAQ]], ai = false, pages = { [[战士]] } },
  [ [[v5748eaic9qqk]] ] = { t = [[战士能重训哪些专长]], q = [[我能在4级、8级等等级重训哪些专长？]], a = [[《核心规则书》中的职业条目是以角色为单一职业（未兼职）为前提写成的。战士重训专长的能力，允许你重训你的一项战士奖励专长（1级、2级、4级等等级获得的）。你不能用它重训来自其他来源的专长（无论是否为战斗专长），比如你在1级、3级等等级获得的专长、1级人类奖励专长，或来自其他职业的奖励专长。

你可能想在角色卡上给你的战士奖励专长加个星号，以便日后轻松判断可以重训哪些专长。]], book = [[核心规则书]], date = [[2013/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qqk]], cat = [[FAQ]], ai = false, pages = { [[战士]] } },
  [ [[v5748eaic9o76]] ] = { t = [[飞行斜向爬升]], q = [[当角色或生物在飞行、并决定以45度角上升时，规则说它以半速移动。那么以这种方式斜向上升时，斜线数格的规则还适用吗？]], a = [[不适用。由于游戏通常被假定在二维平面上进行，即使表现三维战斗时也是如此，上升的规则是用速度减半来处理的，而不是让玩家和GM去确定斜向的垂直移动距离。]], book = [[核心规则书]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o76]], cat = [[FAQ]], ai = false, pages = { [[飞行]] } },
  [ [[v5748eaic9u63]] ] = { t = [[飞行与魔法飞行]], q = [=[被[[麻痹]]或[[震慑]]的生物还能靠魔法飞行继续飞行吗？拥有魔法飞行的生物是否因为没有“天生的”飞行速度，就不适用飞行检定的加值或减值？飞行是否使生物免疫[[措手不及]]？]=], a = [=[不能，任何失去全部动作的生物都无法采取动作进行飞行检定来原地盘旋，因此会自动坠落。这包括被麻痹、震慑或[[晕眩]]的生物。魔法飞行也没有任何不同，即便是麻痹也一样，因为它不是纯粹的精神动作。敏捷为0的生物无法飞行，而麻痹会把生物的敏捷设为0。

尽管飞行技能提到机动性的加值和减值适用于具有天生飞行速度的生物，但它们适用于任何飞行速度。如果它们不适用于以人造手段或魔法获得飞行能力的生物，那么这些机动性（比如飞行术所列的良好机动性）就不会有任何游戏效果。

最后，“飞行时你不被视为措手不及”这句话的意思是，飞行（与用特技保持平衡或攀爬不同）不会自动使你措手不及，也不会迫使你失去敏捷加值对AC的加值；它并不意味着飞行使生物免疫被打个措手不及。]=], book = [[核心规则书]], date = [[2015/01/12]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9u63]], cat = [[FAQ]], ai = true, pages = { [[飞行]], [[飞行术]] } },
  [ [[v5748eaic9r85]] ] = { t = [[自由动作的数量]], q = [[我一轮能进行多少个自由动作？]], a = [[《核心规则书》第181页说：

“自由动作：自由动作只消耗极少的时间和精力。你可以在进行其他动作的同时，正常地进行一个或多个自由动作。不过，你实际上能免费做的事情有合理的限度，由GM决定。”

《核心规则书》第188页说：

“自由动作完全不花任何时间，不过你在一轮中可以进行的自由动作数量可能有所限制。”

