  [ [[v5748eaic9shq]] ] = { t = [[借机攻击中的自由动作]], q = [=[你能在[[借机攻击]]期间进行自由动作吗？例如，在借机攻击命中后，你能使用[[攫抓(怪物能力)|攫抓]]、[[摔绊(怪物能力)|摔绊]]、[[拉拽]]或[[推离]]这些通用怪物规则吗？它们需要自由动作，而自由动作不能在非自己回合使用。那[[接石]]呢？它似乎只能在非自己回合使用。]=], a = [[虽然你在自己的回合之外不能进行大多数自由动作，但攫抓、摔绊、拉拽、推离和接石的自由动作都可以在非自己回合使用。这一点会在日后的勘误中体现。]], book = [[核心规则书]], date = [[2014/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9shq]], cat = [[FAQ]], ai = true, pages = { [[战斗中的动作]] } },
  [ [[v5748eaic9quv]] ] = { t = [[幻音术与可辨识的话语]], q = [[幻音术能制造出可以听懂的话语吗？]], a = [=[制造听起来像话语的声音，与真正制造出可以听懂的话语，是两码事。幻音术可以听起来像人们在交谈，但任何听到的人都无法分辨出这些“人”在说什么。毕竟它只是一个0环法术，不应该像[[腹语术]]（一个更高环的法术）那样强。]=], book = [[核心规则书]], date = [[2013/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9quv]], cat = [[FAQ]], ai = true, pages = { [[幻音术]] } },
